# ============================================================
# apply-catalog-revamp.ps1
# Applies the Catalog page redesign to app.
#
# Changes:
#   Catalog.tsx                                  : Main page — no hero/stats, card grid
#   Catalog/components/CatalogToolbar.tsx        : Title + search + filters + tabs + Add button
#   Catalog/CatalogItemCard.tsx                  : Improved item card design
#   Catalog/CategoryCard.tsx                     : Improved category card design
#
# Usage:
#   Set-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass
#   .\apply-catalog-revamp.ps1
# ============================================================

param([string]$Root = '')
if (-not $Root) {
    $here = Split-Path -Parent $MyInvocation.MyCommand.Path
    if (Test-Path (Join-Path $here 'app')) { $Root = $here }
    else { Write-Error 'Cannot find app. Pass -Root <path>.'; exit 1 }
}
$Root = $Root.TrimEnd('/\').TrimEnd('\/')
Write-Host "Root: $Root" -ForegroundColor Cyan
$ok = 0; $err = 0

function Write-File {
    param([string]$RelPath, [string]$B64)
    $dest = Join-Path $Root $RelPath.Replace('/', [IO.Path]::DirectorySeparatorChar)
    $dir  = Split-Path $dest -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    try {
        $bytes = [Convert]::FromBase64String($B64)
        [IO.File]::WriteAllBytes($dest, $bytes)
        Write-Host "  [OK] $RelPath" -ForegroundColor Green
        $script:ok++
    } catch {
        Write-Host "  [FAIL] $RelPath : $_" -ForegroundColor Red
        $script:err++
    }
}

Write-Host ''
Write-Host 'Applying Catalog revamp...' -ForegroundColor Yellow
Write-Host ''

Write-File 'app/src/pages/application/Catalog.tsx' ('')

Write-File 'app/src/pages/application/Catalog/components/CatalogToolbar.tsx' ('')

Write-File 'app/src/pages/application/Catalog/CatalogItemCard.tsx' ('')

Write-File 'app/src/pages/application/Catalog/CategoryCard.tsx' ('')

Write-Host ''
Write-Host "Done. $ok file(s) written, $err error(s)." -ForegroundColor $(if ($err -eq 0) { 'Green' } else { 'Yellow' })
